import {networkPageHTML} from './network.mjs';
import {resourcesHTML} from './resources.mjs';
import {tools} from './catalog.mjs';
export const pages={
 sites:networkPageHTML,
 resources:resourcesHTML,
 about:`<div class="eyebrow">Free online tools at nepocore.com</div><h1>About Nepocore Tools.</h1><p>Nepocore is the free online tools website at <a href="./">nepocore.com</a>. It brings browser-based calculators, image and PDF tools, study utilities and printable worksheets together in one place. Convert a photo, work out a percentage, calculate an IELTS practice score, or tidy up some text — without creating another account.</p><h2>Built around small, real tasks</h2><p>Every tool in this collection performs a real operation. Calculators explain their assumptions, image tools produce downloadable files, and text utilities keep your input on your device. There are no paid tiers or locked downloads.</p><h2>Privacy by design</h2><p>Processing happens in your browser. We do not run a file-upload server. AI background removal downloads its model when requested, then processes the image locally.</p><h2>Free and open</h2><p>The website source is available under AGPL-3.0. Third-party packages keep their own license notices. <a href="./source.zip" download>Download the source code</a>, view the <a href="https://github.com/Nabi004646/nepocore" target="_blank" rel="noopener noreferrer">Nepocore GitHub repository</a>, or <a href="./tools/">explore all ${tools.length} tools</a>.</p>`,
 privacy:`<div class="eyebrow">Your work stays yours</div><h1>A simple privacy promise.</h1><p>Most tools process your files and inputs locally in your browser. Nepocore does not upload, store, or sell your images, PDFs, calculator entries, or text. Text-to-speech uses your selected system voice; online voices may contact their speech provider as described below.</p><h2>What stays on this device</h2><p>Favorites, theme, layout and motion preferences are saved in local storage. Flashcards and packing lists are saved only when you choose Save on this device. They are not sent to us. You can remove them by clearing this website’s site data in your browser. Other tool inputs, including reproductive-health and family journals, stay in this page session unless you explicitly export them. They are not added to URL queries.</p><h2>Text-to-speech voices</h2><p>Text-to-speech uses your browser or operating system. Device voices can work locally; voices labeled online may send the text to their speech provider and require a network connection. Choose a device voice for local playback when one is available. Nepocore does not receive the text.</p><h2>Camera and microphone</h2><p>Photo tools request camera access only after you choose Use camera. The recorder requests microphone access only after Record. Captures are processed locally; active tracks are stopped when you stop or leave the tool. Uploaded photos are an alternative to using a camera.</p><h2>Downloads and third-party resources</h2><p>Downloaded results are saved where your browser places them. The interface fonts are served with the website. AI background removal requests model and runtime assets from IMG.LY’s CDN on first use; the CDN receives ordinary network request details such as IP address, but does not receive your image. OCR can also download its engine and language data from jsDelivr or the Tesseract language-data host. These requests do not include your image. The browser may cache these assets.</p><h2>Hosting</h2><p>The hosting provider handles ordinary web traffic and may maintain access or security logs. Its policies govern that infrastructure. Advertising is disabled. Nepocore uses Google Analytics to understand visits and website usage; see the analytics details below.</p><h2>Your choices</h2><p>You can use the standard tools without AI model downloads. Close or refresh a tool to clear its in-memory input. Clear site data to remove local preferences and caches. Contact <a href="mailto:admin@nepocore.com">admin@nepocore.com</a> with privacy questions.</p>`,
 terms:`<div class="eyebrow">A few helpful ground rules</div><h1>Terms of use.</h1><p>Nepocore provides free browser-based utilities for everyday tasks. By using the site, you agree to use these tools lawfully and responsibly.</p><h2>Check the important things</h2><p>Outputs are provided as-is. Financial calculators are estimates, not financial advice. Health and pregnancy calculations are informational estimates, not diagnoses, treatment plans or reliable contraception. Family journals do not assess symptoms or clinical risk. No clinical review is claimed. The cuteness meter produces explicitly randomized entertainment scores; it does not analyze attractiveness. IELTS raw-score conversions are practice estimates and do not replace official test results. Review important results before relying on them.</p><h2>Your files and content</h2><p>You retain responsibility for files and text you process. Only use content you have the right to use. Downloads may change formatting, quality, metadata, or transparency. Keep original copies when editing files.</p><h2>Availability and browser support</h2><p>Tools depend on browser capabilities and available device memory. AI background removal also depends on downloading third-party model assets. We cannot guarantee uninterrupted availability, perfect cutouts, universal format support, or compatibility with every device.</p><h2>Open-source licenses</h2><p>The application is offered under AGPL-3.0. QR generation and PDF processing include their respective open-source license notices. IMG.LY background removal is also AGPL-3.0. Review the included licenses when redistributing this website.</p><h2>Contact</h2><p>Questions or corrections: <a href="mailto:admin@nepocore.com">admin@nepocore.com</a>.</p>`,
 faq:`<div class="eyebrow">A little clarity</div><h1>Good questions.</h1>${[
 ['Are all tools really free?','Yes. This collection has no paid tier, account requirement, download gate or subscription.'],
 ['Do you upload my files?','No. Images, PDFs and text are processed in your browser. AI background removal downloads its model to your device, then runs locally.'],
 ['Which image formats can I convert?','You can export JPEG, PNG or WebP when supported by your browser. Import works with common browser-readable formats, including JPEG, PNG, WebP, GIF, BMP and AVIF. HEIC, RAW and Photoshop files are not supported. Animated images are flattened to a single frame.'],
 ['Why is background removal slower the first time?','AI mode downloads a model and runtime assets before processing. It needs an internet connection for that first download, device memory, and a modern browser. Solid-color mode is a faster local option for plain backgrounds.'],
 ['Are IELTS scores official?','The overall calculator follows IELTS averaging and rounding rules. Listening and reading converters show indicative practice bands; actual raw-score boundaries can vary by test version.'],
 ['Can I use the website offline?','After a successful online visit, supported browsers cache the main tool interface. Core tools work offline once cached. AI and OCR assets may need a network connection if they have not been cached.'],
 ['What are the file limits?','Images are limited to 25 MB each and 24 megapixels. PDF processing is limited to 60 MB combined. Large files can still exceed the available memory on smaller devices.'],
 ['How do the fun photo scores work?','The cuteness meter makes a randomized entertainment card from a photo. It does not measure beauty, personality or health. Photos stay on your device.'],
 ['Can I use my camera or microphone?','On supported HTTPS browsers, use the explicit camera or recording button and choose whether to grant permission. Photo uploads are available instead of a camera. Hardware and format support vary.'],
 ['How do I save a resume or invoice as PDF?','Use Print / Save PDF, then choose your browser or operating system’s PDF destination. A standalone HTML download is also available.'],
 ['Are health and pregnancy results medical advice?','No. Formulas, assumptions and source links are displayed. Due dates and cycle dates are estimates, and journals do not interpret symptoms. These tools do not replace professional care.'],
 ['What dates do Nepal tools support?','BS conversion covers 2000–2090, corresponding to AD 1943-04-14–2034-04-13. The holiday calendar is the sourced BS 2083 notice and shows scope restrictions.'],
 ['Where did my download go?','Check your browser’s Downloads list. The file is saved using your browser’s usual download settings.'],
 ['Can I host this on my own domain?','Yes. Download the source ZIP, unpack it, and upload the website files to any static host. Follow the included README and open-source license requirements.']
 ].map(([q,a])=>`<details><summary>${q}</summary><p>${a}</p></details>`).join('')}`,
 contact:`<div class="eyebrow">Let’s make the little things better</div><h1>Say hello.</h1><p>Found a calculation that needs a second look, spotted a bug, or have an idea for a useful tool? Send a note to <a href="mailto:admin@nepocore.com">admin@nepocore.com</a>.</p><h2>Help us reproduce the problem</h2><p>Include the tool name, your browser, what you expected, and what happened. Use sample data rather than sensitive personal information. We do not receive the files you process, so a clear description helps.</p><a class="btn primary" href="mailto:admin@nepocore.com?subject=Nepocore%20tool%20feedback">Write an email ↗</a><p class="form-note">This opens your email app. No form submission or account is required.</p>`
};
const dated='<p class="policy-date">Last updated: <time datetime="2026-10-28">28 October 2026</time></p>';
pages.security=`<div class="eyebrow">APPLICATION SECURITY</div><h1>Keep the task simple.<br>Keep the boundaries clear.</h1><p>Nepocore processes tool inputs in your browser and has no application file-upload server. That reduces the need to share a file with a processing service. It does not make every file, export, device or website automatically safe.</p><h2>How inputs are handled</h2><p>Displayed user text is escaped, Markdown previews use a bundled sanitizer, and image/PDF operations apply file-size, page-count and output limits. PDF tools use a local PDF.js core and worker without a document action runner. HAR logs are inspected without replaying their requests. Native browser cryptography requires a supported secure context.</p><h2>What you control</h2><p>Camera and microphone start only after the relevant action and permission choice. Optional Save on this device records remain in that browser’s local storage. This is not an encrypted vault or cloud backup; another person using the same browser profile may be able to see saved records. Clear records and exported files separately when needed.</p><h2>External resources and future changes</h2><p>Optional OCR and background-removal engines may download resources from third-party hosts, and online system voices may contact their providers. See <a href="./privacy/">Privacy</a>. Advertising is disabled. Google Analytics measures website usage as described in the privacy policy. A future ad, account or server integration needs a new security and privacy review.</p><h2>Review limits</h2><p>The v7 update received a focused source and browser review, including tested Markdown and SVG input cases. This is not an independent penetration test, certification, malware scanner or guarantee of a vulnerability-free application. Hosting security headers depend on the actual provider. Keep your browser updated and verify important results.</p><h2>Report a security issue</h2><p>Email <a href="mailto:admin@nepocore.com?subject=Nepocore%20security%20report">admin@nepocore.com</a> with the affected tool URL, browser and a minimal reproduction using synthetic data. Do not send real credentials, production secrets, sensitive HAR logs or private documents. No bug-bounty or response-time commitment is implied.</p><p>The downloadable <a href="./source.zip" download>source package</a> includes SECURITY.md with the review scope and implementation notes.</p>${dated}`;
pages.about+=`<h2>Who is behind Nepocore?</h2><p>Nepocore is Nabin Kunwar’s independent toolkit project. Its purpose is to make common image, document, study and planning tasks easier to complete in a browser. The project is not a bank, healthcare provider, school, government service or Google product.</p><h2>Tools and field notes</h2><p>The toolkit includes ${tools.length} tools and <a href="./blog/">35 original practical guides</a>. Guides explain actual settings, worked examples and limitations. They were prepared with AI assistance and linked references; no professional or independent editorial review is claimed. Read the <a href="./editorial-policy/">editorial and corrections policy</a> for the method and how to report an issue.</p><h2>How the site is supported</h2><p>This version has no advertising or affiliate links. Google Analytics helps us understand website usage. Advertising may be considered later and would be labeled and described in the <a href="./advertising-policy/">advertising policy</a> and privacy notices before activation.</p>${dated}`;
pages.privacy+=`<h2>Optional planning records</h2><p>Budget, subscription, inventory, cash-flow, room, seating and pantry tables can be saved only when you select Save on this device. Habit records use the same explicit choice. Data is stored in this browser’s local storage under this site’s origin, without account sync. Unchecking the choice removes that tool’s saved record. JSON and CSV exports are files you control. Browser storage and device backups may retain data until you delete it; this is not a secure vault.</p><h2>Guides and contact email</h2><p>Reading guides does not submit your tool inputs. If you email us, your email provider and ours handle the message, address and any attachments. Do not attach private photos, financial records, medical information, passwords or production keys to a bug report. We use correspondence to respond to the issue and do not set a fixed retention period or promise a response time.</p><h2>Advertising is currently disabled</h2><p>No Google AdSense script or advertising cookie is included in this release. Google Analytics is described separately below. The following describes a possible future advertising integration. If Google ads are enabled, third-party vendors including Google may use cookies or similar identifiers to serve and measure advertising. Personalized advertising can be based on visits to this and other websites. Google and advertising partners may receive IP addresses, browser/device details, page addresses and consent choices.</p><p>Before activation, this notice must identify the actual vendors, purposes, applicable consent controls and retention information. Where required, visitors must be offered appropriate consent and withdrawal choices. For personalized ads in the EEA, UK and Switzerland, Google requires a Google-certified CMP integrated with the IAB TCF. A general cookie notice is not a substitute for that setup.</p><p>Google provides <a href="https://myadcenter.google.com/" target="_blank" rel="noopener noreferrer">My Ad Center advertising controls</a> and information on <a href="https://policies.google.com/technologies/partner-sites" target="_blank" rel="noopener noreferrer">data use on partner sites</a>. Additional vendor choices, if applicable, would be listed before those vendors are enabled. Analytics is currently installed using the standard Google tag. This site does not currently provide a consent panel.</p><h2>Requests and policy changes</h2><p>Contact <a href="mailto:admin@nepocore.com?subject=Nepocore%20privacy%20request">admin@nepocore.com</a> about access, correction or deletion of correspondence we hold, or another privacy concern. Local-only tool inputs cannot be retrieved or deleted remotely by us; clear the relevant saved record or browser site data. Applicable rights depend on your location and circumstances. We will update this page when data practices change. See the <a href="./cookies/">cookie and storage policy</a> for device controls.</p>${dated}`;
pages.terms+=`<h2>Additional utility limits</h2><p>PDF image-based exports can remove selectable text and interactive features. Drawn signatures are images, not certificate-backed digital signatures. Passport photo layouts do not certify acceptance. Shipping labels do not purchase postage. Security utilities do not authorize access or execute network actions. Money tools are simplified arithmetic models, and local trackers are not permanent or shared databases.</p><h2>Responsible use and third-party references</h2><p>Do not use the tools to violate privacy, intellectual-property rights or applicable law. We do not host a public gallery of uploaded content. Linked third-party services and references have their own terms and may change. External links are provided for context, not an endorsement or a guarantee of availability.</p><h2>Content and corrections</h2><p>Guides are general instructions prepared with AI assistance. Important outputs and current requirements should be checked with the relevant source. Report an error through the <a href="./contact/">contact page</a>. The <a href="./disclaimer/">disclaimer</a> and <a href="./editorial-policy/">editorial policy</a> explain the scope.</p>${dated}`;
pages.contact+=`<h2>Which kind of message?</h2><ul><li><a href="mailto:admin@nepocore.com?subject=Nepocore%20tool%20bug">Tool bug or calculation issue</a>: include a minimal example and the expected result.</li><li><a href="mailto:admin@nepocore.com?subject=Nepocore%20guide%20correction">Guide correction</a>: include the guide URL, passage and a reliable reference.</li><li><a href="mailto:admin@nepocore.com?subject=Nepocore%20privacy%20request">Privacy request</a>: describe the information involved without sending sensitive tool inputs.</li><li><a href="mailto:admin@nepocore.com?subject=Nepocore%20accessibility">Accessibility feedback</a>: describe the browser, assistive technology and blocked action.</li></ul><p>This site is operated as Nabin Kunwar’s independent Nepocore project. It does not offer emergency, medical, legal or financial support. There is no live support chat or guaranteed response time.</p>${dated}`;
pages.faq+=`<details><summary>Are these guides written by experts?</summary><p>They are original practical instructions prepared with AI assistance using the tools’ behavior and linked sources. No professional review, clinical credentials or independent testing of every device is claimed. Corrections are welcome.</p></details><details><summary>Is Nepocore approved by Google AdSense?</summary><p>No approval is claimed. This release has no ads. Any future application depends on the publisher’s account, publicly accessible hosting, policy compliance and Google’s review. A guide count or a set of policy pages does not guarantee approval.</p></details><details><summary>What limits apply to the new PDF tools?</summary><p>PDF to images, text extraction and compression accept one unprotected PDF up to 30 MB. Image export supports up to 30 selected pages, text extraction up to 100 and image-based compression up to 40 pages. These limits differ from the older merge and extraction tools; use each interface’s displayed limit.</p></details>${dated}`;
pages.cookies=`<div class="eyebrow">YOUR BROWSER. YOUR CHOICES.</div><h1>Cookie & storage policy.</h1><p>Nepocore uses Google Analytics for website usage measurement. The Google tag can use cookies to distinguish visits. Advertising is disabled. It uses browser storage and caching for specific interface and optional saving features. Cookies set by a hosting sign-in or infrastructure service, if present, are governed by that provider.</p><h2>What the application stores</h2><div class="article-table"><table><thead><tr><th>Feature</th><th>Storage and purpose</th><th>Choice</th></tr></thead><tbody><tr><td>Google Analytics</td><td>Google tag and analytics cookies for website usage measurement</td><td>Browser cookie controls or the Google Analytics opt-out browser add-on</td></tr><tr><td>Theme, layout, motion and favorites</td><td>Local storage in this browser</td><td>Change the preference or clear site data</td></tr><tr><td>Optional trackers and lists</td><td>Local storage for the selected tool</td><td>Save on this device is opt-in; uncheck to remove</td></tr><tr><td>Interface and engine assets</td><td>Service-worker/browser cache for repeat visits and limited offline use</td><td>Clear site data and cached files</td></tr><tr><td>Current tool inputs</td><td>In-memory page session unless explicitly saved/exported</td><td>Leave or refresh the tool</td></tr></tbody></table></div><h2>Duration and device access</h2><p>Local storage persists until you or the browser removes it; there is no fixed automatic expiry. Cache entries can be replaced or evicted. Other users of the same browser profile may be able to see saved records. An exported file is separate from browser storage and must be deleted separately.</p><h2>How to remove records</h2><p>Uncheck Save on this device in a tool to remove its saved record. Browser settings for this site can clear local storage, cookies, cached files and service-worker data. Clearing these may reset favorites and preferences and require engine assets to download again. Changing browsers or domains does not transfer saved records.</p><h2>Future advertising choices</h2><p>Advertising is disabled. If it is enabled later, the actual vendors, purposes and consent controls must be disclosed before use. Required consent must use an appropriate implementation; this policy page is not a certified consent-management platform. See <a href="./privacy/">Privacy</a> and <a href="./advertising-policy/">Advertising</a> for the current status.</p>${dated}`;
pages.disclaimer=`<div class="eyebrow">CLEAR LIMITS MAKE BETTER TOOLS</div><h1>Tool & content disclaimer.</h1><p>Nepocore provides general-purpose calculations, file transformations, manual records and educational guides. Results depend on your inputs, the stated model and browser capabilities. Keep originals and verify important outputs.</p><h2>Health, pregnancy and wellbeing</h2><p>Health and pregnancy calculators are informational estimates. They do not diagnose, interpret symptoms, prescribe treatment, establish fetal health or provide reliable contraception. Journals record entries without clinical assessment. No medical professional review is claimed. Use an appropriate healthcare service for personal care decisions.</p><h2>Money and business</h2><p>Budget, debt, subscription, cash-flow and other money tools perform simplified arithmetic. They do not connect to accounts, assess suitability, provide financial advice or create audited accounts. Costs, interest rules, taxes and fees may differ from the assumptions shown. Verify actual terms and records.</p><h2>Education, games and entertainment</h2><p>Practice scores do not replace official test results. Puzzle difficulty and typing results are practice measures. The cuteness meter explicitly produces random entertainment scores; it does not analyze attractiveness, personality, age or health.</p><h2>Images and documents</h2><p>Exports can change metadata, quality, transparency, text layers, forms, links or signatures. A signature image is not a verified digital signature. A passport photo layout is not an acceptance certificate. An address label is not postage. Keep the original and check the receiving organization’s current requirements.</p><h2>Security and regional information</h2><p>Security tools are local learning and diagnostic utilities, not authorization to access systems or guarantees of safety. Nepal date conversion is limited to the bundled range; holiday records have a specific source year and scope. Verify deadlines and closures with the relevant authority.</p><h2>Guides and references</h2><p>Guides were prepared with AI assistance and may contain errors. Sources explain underlying methods and are not endorsements. Report an issue via <a href="./contact/">Contact</a>. Read the <a href="./terms/">terms</a> and <a href="./editorial-policy/">editorial policy</a> for further context.</p>${dated}`;
pages['editorial-policy']=`<div class="eyebrow">HOW THESE FIELD NOTES ARE MADE</div><h1>Editorial & corrections policy.</h1><p>Nepocore publishes original practical instructions for its browser tools. The guides aim to answer a specific task with steps, worked examples, tradeoffs and relevant source links. They are not a news feed or a substitute for professional advice.</p><h2>Authorship and AI assistance</h2><p>The byline Nepocore identifies the project, not a credentialed professional or a fictional editorial team. These guides were drafted with AI assistance using the implemented tool behavior and linked references. No independent human review, expert certification or first-hand product test is claimed unless a future article explicitly documents it.</p><h2>Source selection and original examples</h2><p>Technical explanations favor official documentation, standards and project references. Regional information links to the relevant authority when available. Worked examples are original and distinguish entered assumptions from measured results. A source link supports the associated method, not every possible application of a tool.</p><h2>Scope and high-stakes topics</h2><p>Money guides explain arithmetic models and their limitations. This blog does not publish individualized medical, legal or financial recommendations. Health and pregnancy tool pages disclose their informational scope and do not claim clinical review. Visitors should verify current requirements with the receiving organization or an appropriate professional.</p><h2>Dates and updates</h2><p>Publication and modification dates describe the content version. Dates are not automatically refreshed to imply new research. A guide is updated when its instructions, calculation, source or limitations change materially. External policies and recipient requirements can change between updates.</p><h2>Corrections</h2><p>Email <a href="mailto:admin@nepocore.com?subject=Nepocore%20guide%20correction">admin@nepocore.com</a> with the URL, the issue, a reproducible example where relevant and a reliable reference. Use sample data. Confirmed issues should be corrected in the affected content and tool; substantial corrections should be explained on the page. There is no guaranteed response deadline.</p><h2>Commercial independence</h2><p>This release has no paid placements, affiliate links or advertising. Future sponsorship or advertising would be labeled and would not buy a favorable calculation result or an unsupported claim. See the <a href="./advertising-policy/">advertising policy</a>.</p>${dated}`;
pages.accessibility=`<div class="eyebrow">USEFUL SHOULD BE REACHABLE</div><h1>Accessibility statement.</h1><p>Nepocore aims to make common tasks usable on small screens and with a keyboard. The interface includes labeled fields, visible focus, a skip link, semantic headings, result status messages, color-theme controls and reduced-motion support. These features are ongoing work, not a claim of certified WCAG conformance.</p><h2>Ways to adjust the experience</h2><p>Use the theme button for a different color scheme and the motion button to pause decorative animation. System reduced-motion preferences are respected. Browser zoom can enlarge text. Most tools support text entry and file uploads without camera access.</p><h2>Known limits</h2><p>Drawing a signature, positioning some image crops and manipulating visual designs can require pointer input. The room planner also provides numeric positions as an alternative to dragging. Generated raster images and many printable PDFs do not contain a fully tagged accessible document structure. Provide a text description or another accessible version when sharing them.</p><p>Speech synthesis depends on installed browser or operating-system voices. Camera, microphone, clipboard, download and print features vary across browsers and assistive technologies. Some complex data tables may require horizontal scrolling.</p><h2>Report a barrier</h2><p>Email <a href="mailto:admin@nepocore.com?subject=Nepocore%20accessibility">admin@nepocore.com</a> with the tool URL, blocked action, browser and assistive technology if you wish to share it. A sample input is helpful; private files are unnecessary. We welcome concrete reports and will use them to improve the relevant interaction.</p>${dated}`;
pages['advertising-policy']=`<div class="eyebrow">SUPPORT WITHOUT SURPRISES</div><h1>Advertising policy.</h1><p><strong>Current status: no advertising is active.</strong> Nepocore has no AdSense code, sponsored results, affiliate links or ad-unlock downloads in this release. No Google approval or partnership is claimed.</p><h2>Principles for a future integration</h2><p>Any future ad must be clearly distinguishable from content and labeled appropriately. A visitor will not be asked to click ads to support the site or unlock a file. Ads must not obscure controls or imitate upload, download, navigation or calculation buttons.</p><h2>Placement boundaries</h2><p>The planned initial scope is suitable general-audience editorial guide pages after account, consent and policy review. This is the project’s conservative placement choice, not a claim that Google universally bans ads on all other page types. Tool controls, upload areas, download dialogs, errors, empty-result screens, child-oriented education activities and games will remain outside that initial scope. Privacy and cookie pages must remain free of ad and consent-script tags.</p><h2>Privacy and consent before activation</h2><p>The operator must use real publisher details, confirm publicly accessible hosting and configure applicable consent requirements. Personalized Google ads for users in the EEA, UK and Switzerland require a Google-certified CMP integrated with the IAB TCF. A generic cookie banner is not enough. Any integration must update the <a href="./privacy/">privacy</a> and <a href="./cookies/">storage</a> disclosures to reflect actual vendors and choices.</p><h2>Editorial independence and reports</h2><p>Advertising will not change calculator arithmetic or buy an unsubstantiated recommendation. Sponsored editorial content, if ever introduced, must be identified. Report a misleading placement or privacy concern through <a href="./contact/">Contact</a>.</p><p>Approval and continued eligibility are decisions of the advertising provider. A number of articles, technical SEO features or policy pages cannot guarantee acceptance.</p>${dated}`;

const analyticsUpdated='<p class="policy-date">Analytics notice updated: <time datetime="2026-11-05">5 November 2026</time></p>';
pages.privacy+=`<h2>Google Analytics</h2><p>Nepocore uses Google Analytics with measurement ID G-R6E4FXVHNG to measure visits and website usage. The Google tag sends page and usage events to Google and can use cookies to distinguish visits. Google receives network request details and browser/device information. We do not add your tool inputs, uploaded files or generated results to analytics events.</p><p>Read <a href="https://policies.google.com/technologies/partner-sites" target="_blank" rel="noopener noreferrer">how Google uses information from sites that use its services</a>. You can manage cookies in your browser or use the <a href="https://tools.google.com/dlpage/gaoptout" target="_blank" rel="noopener noreferrer">Google Analytics opt-out browser add-on</a>. Clearing cookies removes stored identifiers but does not prevent new ones on a later visit.</p>${analyticsUpdated}`;
pages.cookies+=`<h2>Analytics controls</h2><p>Manage analytics cookies through your browser settings or the <a href="https://tools.google.com/dlpage/gaoptout" target="_blank" rel="noopener noreferrer">Google Analytics opt-out browser add-on</a>. See the <a href="./privacy/">privacy policy</a> for the Google Analytics disclosure.</p>${analyticsUpdated}`;
